example.code:
enum OperatingSystem
{
   [DisplayText("MS-DOS")]
   MsDos,

   [DisplayText("Windows 98")]
   Win98,

   [DisplayText("Windows XP")]
   Xp,

   [DisplayText("Windows Vista")]
   Vista,

   [DisplayText("Windows 7")]
   Seven,
}

public string GetMyOSName()
{
    var myOS = OperatingSystem.Seven;
    return myOS.DisplayText();
}
